import{_ as i,o as a,c as s,ae as l}from"./chunks/framework.jfJLTIcL.js";const k=JSON.parse('{"title":"发布环境迁移指南（mac 机器切换）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/release-migration.md","filePath":"zh-CN/release-migration.md","lastUpdated":1778950365000}'),t={name:"zh-CN/release-migration.md"};function d(o,e,n,r,c,h){return a(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="发布环境迁移指南-mac-机器切换" tabindex="-1">发布环境迁移指南（mac 机器切换） <a class="header-anchor" href="#发布环境迁移指南-mac-机器切换" aria-label="Permalink to &quot;发布环境迁移指南（mac 机器切换）&quot;">​</a></h1><p>本页用于记录 macOS 发布环境在不同机器之间迁移的标准流程，重点对应 <code>scripts/migrate-release-env.sh</code>（<code>yarn release:migrate</code>）。</p><h2 id="一句话流程" tabindex="-1">一句话流程 <a class="header-anchor" href="#一句话流程" aria-label="Permalink to &quot;一句话流程&quot;">​</a></h2><ul><li>迁出（备份）：<code>yarn release:migrate</code></li><li>迁入（恢复）：<code>yarn release:migrate --input &lt;备份文件&gt; --decrypt</code></li><li>迁出后建议加密：带上 <code>--encrypt</code></li><li>不确定走哪一步时：加 <code>--ask</code> 让脚本提示你选择</li></ul><h2 id="备份-从旧机器导出" tabindex="-1">备份（从旧机器导出） <a class="header-anchor" href="#备份-从旧机器导出" aria-label="Permalink to &quot;备份（从旧机器导出）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orulink-2026-05</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --encrypt</span></span></code></pre></div><p>会自动打包以下内容到主目录下（默认文件名为 <code>~/release-&lt;时间&gt;.tar.gz</code>，加密时为 <code>.enc</code>）：</p><ul><li><code>~/.tauri/vilab-updater.key</code></li><li><code>~/.tauri/vilab-updater.key.pub</code></li><li><code>~/.tauri/vilab-updater.password</code></li><li><code>~/orulink-secrets</code></li><li><code>~/.orulink-build-secrets</code></li><li><code>.vilab-release-env.sh</code>（仅环境变量模板，默认不写明文）</li></ul><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><ul><li><code>--include-env</code>：把当前 shell 中发布相关环境变量写入备份中的 <code>.vilab-release-env.sh</code>（默认关闭，避免明文泄露）。若开启会强制加密。</li><li><code>MIGRATE_SECRET_PASSPHRASE</code>：如设置，会自动复用为备份加密口令。</li></ul><h2 id="恢复-在新机器导入" tabindex="-1">恢复（在新机器导入） <a class="header-anchor" href="#恢复-在新机器导入" aria-label="Permalink to &quot;恢复（在新机器导入）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/release-xxxx.tar.gz.enc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decrypt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --import-certificate</span></span></code></pre></div><p>恢复后会执行：</p><ul><li>拷贝文件到目标目录</li><li>修正关键文件权限（<code>600/700</code>）</li><li>如果本地具备 updater 私钥与公钥，会尝试跑一遍 <code>node scripts/verify-updater-signing-key.mjs</code></li><li>可选导入开发者证书到 login keychain（配合 <code>--import-certificate</code>）</li></ul><h3 id="后续你需要手工核对" tabindex="-1">后续你需要手工核对 <a class="header-anchor" href="#后续你需要手工核对" aria-label="Permalink to &quot;后续你需要手工核对&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/verify-updater-signing-key.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">security</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> find-identity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codesigning</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Library/Keychains/login.keychain-db&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Developer ID Application&quot;</span></span></code></pre></div><h2 id="自动识别规则" tabindex="-1">自动识别规则 <a class="header-anchor" href="#自动识别规则" aria-label="Permalink to &quot;自动识别规则&quot;">​</a></h2><p><code>migrate-release-env.sh</code> 会按以下规则判断方向：</p><ul><li>有 <code>--input</code> 参数 ⇒ 自动走“迁入（restore）”</li><li>其他情况 ⇒ 默认走“迁出（backup）”</li><li>加 <code>--ask</code> 可在未显式指定时在终端询问你是“迁入”还是“迁出”</li></ul><h2 id="脚本参数-可按需选" tabindex="-1">脚本参数（可按需选） <a class="header-anchor" href="#脚本参数-可按需选" aria-label="Permalink to &quot;脚本参数（可按需选）&quot;">​</a></h2><ul><li><code>backup</code>（默认）</li><li><code>restore</code></li><li><code>--output &lt;file&gt;</code>：自定义备份文件路径</li><li><code>--input &lt;file&gt;</code>：恢复文件路径</li><li><code>--encrypt</code>：备份加密（建议）</li><li><code>--decrypt</code>：恢复时解密</li><li><code>--include-env</code>：把发布环境变量写入模板并加密备份（默认关闭）</li><li><code>--import-certificate</code>：恢复后将 <code>.p12</code> 导入钥匙串</li><li><code>--ask</code>：运行前让脚本确认迁移方向</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>只复制脚本是不够的：<strong>核心是密钥和证书文件本身</strong>，必须一起迁移。</li><li>不要把敏感明文口令记到公开记录里；建议每次迁移时使用 <code>--encrypt</code>。</li><li>恢复后仍需按机器实际环境补充 <code>~/.vilab-release-env.sh</code> 中的 placeholder（如 <code>APPLE_PASSWORD</code> 等）。</li></ul>`,23)])])}const u=i(t,[["render",d]]);export{k as __pageData,u as default};
